style.css:
@-moz-document url-prefix("https://www.chess.com") {
/* Hide username component */
  .user-username-component {
    display: none !important;
  }

  /* Hide player avatar component */
  .player-avatar-component,
  .avatar-component {
    display: none !important;
  }

  /* Hide bold text */
  .cc-text-medium-bold {
    display: none !important;
  }

  /* Hide chat room */
  .chat-room-chat {
    display: none !important;
  }

  /* Hide Game Over modal */
  .game-over-modal-content {
    display: none !important;
  }

/* Hide the intro animation with player names */
.vs-splash,
.vs-component,
.game-vs-info,
div[class*="vs-"],
div[class*="game-start"] {
  display: none !important;
}
 
.cc-section-content {
      display: none !important;
}
.cc-section > .cc-section-content {
      display: none !important;

  }
}
